import csv
from collections import OrderedDict
path='/root/weoapr2025all.xls'
# read UTF-16 tab-separated
with open(path, 'r', encoding='utf-16') as f:
    reader = csv.reader(f, delimiter='\t')
    header = next(reader)
    # Map year columns
    year_cols = {int(col): idx for idx, col in enumerate(header) if col.isdigit()}
    # collect for Georgia
    target_codes = {'NGDP_R','NGDP_RPCH'}
    data = {}
    for row in reader:
        if not row:
            continue
        if len(row) < 10:
            continue
        country = row[3]
        subject_code = row[2]
        if country == 'Georgia' and subject_code in target_codes:
            series = {}
            for year in range(2000, 2028):
                idx = year_cols.get(year)
                if idx is not None and idx < len(row):
                    val = row[idx]
                    series[year] = val if val != '' else None
            data[subject_code] = series
            if len(data)==2:
                break

print('found', data.keys())
print('2000', data['NGDP_R'].get(2000), data['NGDP_RPCH'].get(2000))
print('2027', data['NGDP_R'].get(2027), data['NGDP_RPCH'].get(2027))
